HEADER=f'''<a class="skip-link" href="#main">К содержимому</a><header class="header"><div class="header-inner"><a class="brand" href="/" aria-label="Катарсис, главная"><img src="{logo}" alt="" width="40" height="40"><span>КАТАРСИС<small>Настольная ролевая система</small></span></a><button class="menu-toggle" aria-controls="main-nav" aria-expanded="false" aria-label="Открыть меню"><span></span><span></span></button><nav class="topnav" id="main-nav" aria-label="Основная навигация"><a href="/play/#session">За столом</a><a href="/play/#rules">Правила</a><a href="/play/#lore">Мир</a><a class="gm-nav" href="/gm">Мастеру ↗</a><a class="nav-cta" href="/play/#builder">Создать героя <span aria-hidden="true">↗</span></a></nav></div></header>'''
FOOTER=f'''<footer class="shell site-footer-shell"><div class="footer"><div class="footer-brand"><a class="footer-wordmark" href="/">КАТАРСИС<small>Настольная ролевая система</small></a><p>Правила и инструменты, чтобы меньше отвлекаться и больше играть.</p><p class="small">Без аккаунта. Без рекламы и аналитики. Данные персонажа остаются в этом браузере.</p><div class="footer-actions"><a class="button small" href="/play/#builder">Создать персонажа <span aria-hidden="true">↗</span></a><a class="footer-text-link" href="/play/#session">Открыть «За столом»</a></div></div><nav class="footer-column" aria-label="Начать игру"><span class="footer-label">НАЧАТЬ ИГРУ</span><a href="/play/#builder">Конструктор</a><a href="/play/#session">За столом</a><a href="/play/#rules">Правила системы</a><a href="/play/#abilities">Способности</a></nav><nav class="footer-column" aria-label="Справка"><span class="footer-label">СПРАВКА</span><a href="/gm">Инструменты Мастера</a><a href="/updates">История обновлений</a><a href="/privacy">Данные и сохранения</a><a href="/terms">Об использовании</a></nav><div class="footer-meta"><a href="/updates">Версия {VERSION}</a></div></div></footer>''' 
def head(title,description,extra=''):
 return f'''<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · Катарсис</title><meta name="description" content="{description}"><meta property="og:type" content="website"><meta property="og:locale" content="ru_RU"><meta property="og:title" content="{title} · Катарсис"><meta property="og:description" content="{description}"><meta property="og:image" content="{cover}"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#4b2a59"><link rel="icon" href="{logo}"><link rel="stylesheet" href="/site.css"><link rel="stylesheet" href="/site-polish.css">{extra}</head>'''
def page(title,description,main,bodyclass='',extra=''):
 return '<!DOCTYPE html><html lang="ru">'+head(title,description,extra)+f'<body class="{bodyclass}"><div class="scroll-progress" aria-hidden="true"></div>'+HEADER+'<main class="shell" id="main" tabindex="-1">'+main+'</main>'+FOOTER+'<script src="/site.js" defer></script></body></html>'
paths=[('Правила системы','Характеристики, проверки, здоровье, отдых и ремесло.','rules'),('Памятка по бою','Три действия, реакция и понятные пороги попадания.','combat'),('Способности','Знамения, призвания и ключи. Поиск по названиям и эффектам.','abilities'),('Снаряжение','Оружие, защита и вещи для дороги с кошельком персонажа.','shop'),('Карта мира','Поселения и страны на интерактивной карте.','map'),('Хроника мира','Истории городов, единый Свет и тайны Чёрной империи.','lore')]
directory=''.join(f'''<a class="directory-link" href="/play/#{target}" data-search="{title.lower()} {text.lower()}"><span class="chapter-num">0{i+1}</span><div><h3>{title}</h3><p>{text}</p></div><span class="arrow" aria-hidden="true">↗</span></a>''' for i,(title,text,target) in enumerate(paths))
faqs=[('Нужна ли регистрация?','Нет. Конструктор, правила и инструменты Мастера открыты без аккаунта и пароля.'),('Где хранится персонаж?','В браузере на этом устройстве. Автоматической синхронизации между устройствами нет.'),('Можно ли сохранить несколько героев?','Да, до 10 независимых листов. У каждого свои ресурсы, снаряжение, записи и избранное.'),('Как перенести лист на другое устройство?','Экспортируйте героя или всю коллекцию в JSON, затем импортируйте файл в другом браузере. Перед очисткой данных сделайте резервную копию.'),('Подходит ли сайт для телефона?','Да. В режиме «За столом» собраны ресурсы, оружие, выбранные способности и броски активного персонажа.'),('Можно ли играть с бумажным листом?','Да. В разделе персонажей доступны печать A4 и экспорт PDF. Раздаточные материалы можно скачать отдельно.')]
faqhtml=''.join(f'<article class="faq-item"><h3>{q}</h3><p>{a}</p></article>' for q,a in faqs)
main=f'''<section class="home-hero" aria-labelledby="hero-title"><div class="hero-copy"><div class="eyebrow">Настольная ролевая игра · электронный спутник</div><h1 id="hero-title">Твой герой.<br><span>Твой Катарсис.</span></h1><p>Мрачный мир, опасные дороги и выбор, который остаётся за тобой. Создай персонажа и держи всё нужное для игры под рукой.</p><a class="button" href="/play/#builder">Создать персонажа <span aria-hidden="true">↗</span></a><div class="hero-proof"><span class="status-dot" aria-hidden="true"></span>Без регистрации. Лист сохраняется в твоём браузере.</div><div class="return-link">Уже начал историю? <a href="/play/#sheet">Открыть персонажей</a></div></div><div class="cover-object" aria-label="Обложка Катарсиса"><img src="{cover}" alt="Чёрный монолит со щупальцем над горными хребтами" width="1536" height="864" fetchpriority="high"><div class="cover-type"><span>Настольная ролевая система</span><strong>КАТАРСИС</strong></div><div class="cover-colophon"><span>Восемь знамений</span><span>Одна история</span></div></div></section>
<div class="proof-strip" aria-label="Возможности системы"><div class="proof-stat"><strong>08</strong><span>знамений<br>на выбор</span></div><div class="proof-stat"><strong>26</strong><span>призваний<br>для героя</span></div><div class="proof-stat"><strong>212</strong><span>умений и ключей<br>в справочнике</span></div><div class="proof-stat"><strong>31</strong><span>навык<br>для твоих решений</span></div></div>
<section class="home-section" aria-labelledby="tools-title"><div class="section-head reveal"><div><div class="eyebrow">От первого выбора до игровой сессии</div><h2 id="tools-title">История твоя.<br>Рутина на сайте.</h2></div></div><div class="feature-layout"><article class="feature-play reveal"><div class="eyebrow">Режим «За столом»</div><h3>Меньше поисков.<br>Больше игры.</h3><p>Здоровье, стресс, вдохновение, оружие и выбранные умения на одном экране. Изменения сразу попадают в лист персонажа.</p><div class="preview-label">Пример ресурсов персонажа</div><div class="resource-preview" aria-label="Пример записи ресурсов"><div><span>Физическое<br>здоровье</span><strong>12 / 12</strong></div><div><span>Ментальное<br>здоровье</span><strong>10 / 11</strong></div><div><span>Стресс</span><strong>3</strong></div><div><span>Вдохновение</span><strong>2</strong></div></div><a href="/play/#session" class="text-link">Открыть режим игры <span aria-hidden="true">→</span></a></article><div class="feature-notes"><article class="feature-note reveal"><div class="eyebrow">Создание героя</div><h3>Выбор за тобой.<br>Расчёты связаны.</h3><p>Выбери знамение и призвание. Конструктор свяжет характеристики, навыки и здоровье, а личные детали останутся твоими.</p><a class="text-link" href="/play/#builder">К конструктору →</a></article><article class="feature-note reveal"><div class="eyebrow">Сохранения и спокойствие</div><h3>Не потеряй свою историю.</h3><p>До 10 героев, общая резервная копия и отмена последних 20 изменений текущего листа. Частые правила и способности можно закрепить в избранном.</p><a class="text-link" href="/play/#sheet">Мои персонажи →</a></article></div></div></section>
<section class="home-section reveal" aria-labelledby="steps-title"><div class="section-head"><div><div class="eyebrow">Первая игра</div><h2 id="steps-title">Три шага к своему герою</h2></div></div><div class="step-list"><article><span class="step-num">01</span><h3>Найди свой путь</h3><p>Имя, знамение и призвание зададут основу персонажа.</p></article><article><span class="step-num">02</span><h3>Соберись в дорогу</h3><p>Выбери умения, распредели характеристики и купи снаряжение.</p></article><article><span class="step-num">03</span><h3>Садись за стол</h3><p>Открой режим игры на телефоне или распечатай готовый лист.</p></article></div></section>
<section class="tagline-section" aria-label="История рождается за столом"><div class="eyebrow">Катарсис начинается с людей</div><h2 class="word-reveal">Правила дают опору.<br>Историю создаёте вы.</h2><p>Сайт хранит записи и помогает найти нужный приём. Решения, разговоры и последствия остаются за игровым столом.</p></section>
<section class="home-section" aria-labelledby="library-title"><div class="section-head reveal"><div><div class="eyebrow">Твоя книга приключений</div><h2 id="library-title">Открой нужную главу</h2></div><input class="search" id="section-search" type="search" placeholder="Найти раздел…" aria-label="Найти раздел сайта"></div><div class="directory" id="section-cards">{directory}</div><p id="search-empty" role="status" hidden>Раздел не найден. Попробуй «бой», «мир» или «снаряжение».</p></section>
<section class="home-section faq-layout" aria-labelledby="faq-title"><div class="faq-heading reveal"><div class="eyebrow">Перед началом</div><h2 id="faq-title">Несколько простых ответов</h2><p>Где лежит лист, как сохранить героев и что взять с собой на игру.</p></div><div class="faq-list">{faqhtml}</div></section>
<section class="final-call reveal" aria-labelledby="final-title"><div><h2 id="final-title">Осталось дать герою имя.</h2><p>Начни с первого выбора. К готовому листу можно вернуться в этом браузере.</p></div><a class="button" href="/play/#builder">Создать персонажа <span aria-hidden="true">↗</span></a></section>'''
(web/'index.html').write_text(page('Твой герой. Твой Катарсис','Создай героя для Катарсиса. Правила, 26 призваний, листы персонажей и режим игры на телефоне без регистрации.',main,'home-page',f'<link rel="stylesheet" href="/home.css"><link rel="preload" as="image" href="{cover}">'))
# Keep the existing GM and release content; improve only the shared shell.
