privacy='''<section class="page-head"><div class="eyebrow">Твой лист остаётся твоим</div><h1>Данные и сохранения</h1><p>Что хранится в браузере и как не потерять персонажа.</p></section><article class="legal-copy"><h2>Локальные записи</h2><p>Листы персонажей, фотографии, избранное и личные заметки Мастера сохраняются в хранилище браузера на этом устройстве. Аккаунтов и облачной синхронизации на сайте нет.</p><h2>Резервная копия</h2><p>Перед очисткой браузера, сменой устройства или завершением приватного сеанса экспортируй героя или всю коллекцию в JSON. Файл содержит твои записи: передавай его только тем, с кем хочешь ими поделиться.</p><h2>Работа сайта</h2><p>На сайте нет рекламных и аналитических скриптов. Для выдачи страниц хостинг обрабатывает обычные сетевые запросы. Эта страница не обещает отсутствия технических журналов у провайдера хостинга.</p><h2>Удаление</h2><p>Отдельного героя можно удалить в разделе «Персонажи». Очистка данных сайта в настройках браузера удаляет локальные сохранения. Экспортированные файлы при этом остаются там, куда ты их скачал.</p><a class="text-link" href="/play/#sheet">К моим персонажам →</a></article>'''
(web/'privacy.html').write_text(page('Данные и сохранения','Как Катарсис хранит персонажей и личные заметки в браузере.',privacy))
terms='''<section class="page-head"><div class="eyebrow">Перед использованием</div><h1>Об использовании</h1><p>Сайт помогает вести игру, но не заменяет договорённости за столом.</p></section><article class="legal-copy"><h2>Игровые инструменты</h2><p>Применяй способности по их описаниям. Если правило не определено, согласуй решение с Мастером. Наличие кнопки или поля не вводит новое правило.</p><h2>Ответственность за сохранения</h2><p>Храни резервные копии важных персонажей и заметок. Сайт не обещает восстановить данные после очистки браузера, сбоя устройства или удаления сохранения.</p><h2>Права на материалы</h2><p>Эта страница не устанавливает отдельную лицензию на тексты, изображения или другие материалы Катарсиса и не предоставляет права на их перепродажу. Вопросы распространения и использования за пределами игры согласуются с правообладателями.</p><a class="text-link" href="/">Вернуться на главную →</a></article>'''
(web/'terms.html').write_text(page('Об использовании','О работе игровых инструментов и сохранении материалов Катарсиса.',terms))
notfound='''<section class="page-head"><div class="error-code">404 / Дорога обрывается</div><h1>Здесь пока нет главы.</h1><p>Адрес мог измениться, а некоторые материалы сняты с публикации. Твои локальные персонажи от этого не исчезли.</p><div style="margin-top:32px"><a class="button" href="/">На главную →</a></div><a class="text-link" href="/play/#sheet">Открыть персонажей</a></section>'''
(web/'404.html').write_text(page('Страница не найдена','Вернись к правилам и своим персонажам Катарсиса.',notfound))
# Progressive enhancement: static navigation stays usable without JavaScript.
for filename in ['index.html','gm.html','updates.html','privacy.html','terms.html','404.html']:
 p=web/filename;s=BeautifulSoup(p.read_text(),'html.parser')
 if not s.find('noscript'):
  ns=s.new_tag('noscript');st=s.new_tag('style');st.string='@media(max-width:700px){.header-inner{flex-wrap:wrap}.menu-toggle{display:none}.topnav{display:flex;flex-basis:100%;flex-wrap:wrap;gap:12px 24px;padding-top:12px;font-size:14px}}';ns.append(st);s.head.append(ns)
 if filename=='index.html' and not s.find('script',type='application/ld+json'):
  data={'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':x.find('h3').get_text(),'acceptedAnswer':{'@type':'Answer','text':x.find('p').get_text()}} for x in s.select('.faq-item')]};sc=s.new_tag('script',type='application/ld+json');sc.string=json.dumps(data,ensure_ascii=False);s.head.append(sc)
 p.write_text(str(s))
print('Landing, shared navigation, privacy/use pages and branded 404 created.')
